<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800&family=Space+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#D40914; --blue:#0B3D91; --yellow:#F9D507;
    --black:#111111; --white:#F6F4EE; --line:#111111;
    --thick:16px; --thin:6px;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  body{
    background:var(--white);
    color:var(--black);
    font-family:'Space Grotesk',sans-serif;
    line-height:1.6;
  }
  .wrap{max-width:1080px;margin:0 auto;padding:0 24px}

  /* top grid bar */
  .gridbar{display:grid;grid-template-columns:1fr 3fr 1fr;height:14px;border-bottom:var(--thin) solid var(--line)}
  .gridbar div:nth-child(1){background:var(--red)}
  .gridbar div:nth-child(2){background:var(--white)}
  .gridbar div:nth-child(3){background:var(--yellow)}

  header{padding:72px 0 48px;border-bottom:var(--thin) solid var(--line)}
  .kicker{font-family:'Archivo',sans-serif;font-weight:600;letter-spacing:.25em;text-transform:uppercase;font-size:.8rem}
  h1{font-family:'Archivo',sans-serif;font-weight:800;font-size:clamp(2.2rem,6vw,4.5rem);line-height:1.05;text-transform:uppercase;letter-spacing:-.01em;margin:16px 0 8px}
  .sub{font-size:1.15rem;color:#444}
  .sub strong{color:var(--black)}

  main section{padding:64px 0;border-bottom:var(--thin) solid var(--line)}
  h2{font-family:'Archivo',sans-serif;font-weight:800;text-transform:uppercase;letter-spacing:.06em;font-size:1.1rem;margin-bottom:24px;display:flex;align-items:center;gap:12px}
  h2::before{content:"";display:inline-block;width:28px;height:28px;background:var(--black)}

  .hero{display:grid;grid-template-columns:1.1fr 1fr;gap:48px;align-items:center;padding:64px 0;border-bottom:var(--thin) solid var(--line)}
  @media(max-width:800px){.hero{grid-template-columns:1fr}}

  /* the painting, in CSS */
  .canvas-frame{border:var(--thick) solid var(--line);background:#fff;box-shadow:12px 12px 0 var(--black)}
  .composition{display:grid;aspect-ratio:1/1;
    grid-template-columns:57% 6% 1fr;
    grid-template-rows:1fr 6% 32% 6% 14%;
  }
  .c-red{grid-column:1;grid-row:1;background:var(--red)}
  .c-white-top{grid-column:3;grid-row:1;background:#fff}
  .h-rule{grid-column:1 / -1;background:var(--black)}
  .c-white-mid{grid-column:1;grid-row:3;background:#fff}
  .c-yellow{grid-column:1;grid-row:5;background:var(--yellow)}
  .v-rule{grid-column:2;grid-row:1 / 3;background:var(--black)}
  .c-blue{grid-column:3;grid-row:3;background:var(--blue)}
  .c-white-right{grid-column:3;grid-row:5;background:#fff}

  .facts{list-style:none}
  .facts li{display:flex;gap:16px;padding:14px 0;border-bottom:2px solid var(--black)}
  .facts li:last-child{border-bottom:none}
  .facts .k{font-family:'Archivo',sans-serif;font-weight:800;text-transform:uppercase;font-size:.75rem;letter-spacing:.15em;min-width:110px;padding-top:4px}
  .facts .v{flex:1}

  .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--thin)}
  @media(max-width:800px){.cards{grid-template-columns:1fr}}
  .card{border:var(--thin) solid var(--line);padding:28px;background:#fff}
  .card:nth-child(1){border-top:14px solid var(--red)}
  .card:nth-child(2){border-top:14px solid var(--blue)}
  .card:nth-child(3){border-top:14px solid var(--yellow)}
  .card h3{font-family:'Archivo',sans-serif;font-weight:800;text-transform:uppercase;font-size:1rem;margin-bottom:12px}
  .card p{font-size:.95rem;color:#333}

